import expected from './expected-probe-policy-v1.json' with {type:'json'};
export const EXPECTED_POLICY=Object.freeze(expected);
export const PROBE_PHASES=Object.freeze([['stage-2',2,300,5],['stage-10',10,300,5],['soak',10,360,6]]);
