export function parseProbeInvocation(args){if(args.length===1&&args[0]==='--self-check')return{selfCheck:true,runId:null};assert.ok(args.length===2&&args[0]==='--verify-ended-probe18'&&/^--run=[0-9]{13}-[a-f0-9]{8}$/.test(args[1]),'Explicit ended-probe18 flag and originalrunID required');return{selfCheck:false,runId:args[1].slice(6)};}
