export function histogramDelta(before,after){
 assert.equal(before.buckets.length,after.buckets.length);const buckets=after.buckets.map((b,i)=>{assert.equal(b.upperBoundUs,before.buckets[i].upperBoundUs);const count=b.count-before.buckets[i].count;assert.ok(Number.isSafeInteger(count)&&count>=0);return{upperBoundUs:b.upperBoundUs,count};});const count=after.count-before.count;assert.equal(buckets.reduce((a,b)=>a+b.count,0),count);
 const unknown=before.saturated||after.saturated||before.discardedSamples||after.discardedSamples;
 const quantile=p=>{if(!count||unknown)return null;const wanted=Math.ceil(count*p);let n=0;for(const b of buckets){n+=b.count;if(n>=wanted)return b.upperBoundUs;}return null;};
 return{count,sumUs:after.sumUs-before.sumUs,overBudgetCount:after.overBudgetCount-before.overBudgetCount,buckets,p99UpperUs:quantile(.99),p999UpperUs:quantile(.999),quantileKnown:count>0&&!unknown&&quantile(.999)!==null,unknownReasons:[...(!count?['zero-observations']:[]),...(unknown?['saturated-or-discarded-cumulative-input']:[]),...(count&&quantile(.999)===null&&!unknown?['overflow-bucket-upper-bound-unknown']:[])],phaseMaximumUs:null,maximumRule:'Cumulative max is not subtractable; no phase maximum inferred.'};
}
export function phaseTelemetryDeltas(brackets){return brackets.map(p=>{const a=p.afterStart,b=p.beforeEnd;if(!a||!b||a.sampledAtMs>b.sampledAtMs)return{name:p.name,complete:false,reason:'no-inside-phase-sampling-pair',histograms:null};const histograms={};for(const k of['immediateRequests','lifecycleRequests','movementAdmissions','zoneWork','ownerTickDeadlineLag','pendingMovementDeadlineLag']){const x=a.zoneMetrics[k],y=b.zoneMetrics[k];histograms[k]=histogramDelta(x.duration??x,y.duration??y);if(x.duration){histograms[k].successCount=y.successCount-x.successCount;histograms[k].failureCount=y.failureCount-x.failureCount;}}return{name:p.name,complete:true,requestedStartedAtMs:p.startedAtMs,requestedEndedAtMs:p.endedAtMs,sampledStartedAtMs:a.sampledAtMs,sampledEndedAtMs:b.sampledAtMs,unobservedStartEdgeMs:a.sampledAtMs-p.startedAtMs,unobservedEndEdgeMs:p.endedAtMs-b.sampledAtMs,histograms,scope:a.zoneMetrics.scope,definition:'Inside-phase sampled cumulative-bucket differences only. Not lifetime quantiles, exact completephase maxima, clientACK or ingress-to-authoritative-outbound timing.',hardServerSloAdjudicated:false};});}

export function assertRootCleanup(value,runId){assert.equal(value.schemaVersion,1);assert.equal(value.runId,runId);assert.deepEqual(value.ownedPids,[70676,45472]);assert.deepEqual(value.remainingOwnedProcesses,[]);assert.deepEqual(value.remainingOwnedPortListeners,[]);assert.ok(typeof value.observedAt==='string'&&Number.isFinite(Date.parse(value.observedAt)));assert.equal(typeof value.scope,'string');}

